import React, { useState } from 'react';
import { useOSStore } from '../store/useOSStore';
import { INITIAL_SHADOWCHAT_FEED } from '../data/commsData';
import { Plus, Smile, Mail } from 'lucide-react';

export default function CommsApp() {
  const [activeTab, setActiveTab] = useState('comms'); // 'messages' (Personal) | 'comms' (Work/School)
  const [activeContact, setActiveContact] = useState('Aelita');
  const [composing, setComposing] = useState(false);
  const [composeRecipient, setComposeRecipient] = useState('Aelita');
  const [composeSubject, setComposeSubject] = useState('');
  const [composeBody, setComposeBody] = useState('');

  // Initial Data
  const [chatFeed, setChatFeed] = useState(INITIAL_SHADOWCHAT_FEED);
  const [chatInput, setChatInput] = useState('');

  // Contacts lists
  const personalContacts = ['Aelita', 'Odd', 'Yumi', 'Jeremie', 'Ulrich', 'Sissi', 'Nerya'];
  const workSchoolContacts = ['Dean Cassian Rook', 'Dr. Maelis Voss', 'Prof. Corvin Vale', 'Agent Mara Quell', 'Faith Medical'];

  const activeContactsList = activeTab === 'messages' ? personalContacts : workSchoolContacts;

  const handleSendChat = (e) => {
    if ((e.key === 'Enter' || e.type === 'click') && chatInput.trim()) {
      setChatFeed((prev) => [
        ...prev,
        { id: Date.now(), user: 'You (Operative)', team: activeContact, text: chatInput.trim(), time: 'Just now' },
      ]);
      setChatInput('');
      useOSStore.getState().addSkillXP('Communication', 10);
    }
  };

  const handleSendCompose = () => {
    if (!composeSubject.trim() || !composeBody.trim()) return;
    setChatFeed((prev) => [
      ...prev,
      {
        id: Date.now(),
        user: `You (To: ${composeRecipient})`,
        team: composeRecipient,
        text: `[${composeSubject}] ${composeBody}`,
        time: 'Just now',
      },
    ]);
    setComposing(false);
    setComposeSubject('');
    setComposeBody('');
    useOSStore.getState().addSkillXP('Communication', 15);
  };

  return (
    <div className="flex h-full w-full bg-[#240724] text-slate-900 font-sans text-xs select-none p-2.5 overflow-hidden">
      {/* ------------------------------------------------------------------ */}
      {/* LEFT SIDEBAR (EXACT SVG SPEC: WIDTH ~177px, BORDER #4626A4)        */}
      {/* ------------------------------------------------------------------ */}
      <div className="w-44 bg-[#240724] border-r-4 border-[#4626A4] pr-2.5 flex flex-col justify-between shrink-0">
        {/* Top Channel Stack */}
        <div className="space-y-2">
          {/* Header Box */}
          <div className="bg-[#D9D9D9] border-2 border-black p-2 font-mono font-black text-[10px] text-[#1F1F1F] uppercase tracking-wider flex items-center justify-between shadow-sm">
            <span>{activeTab === 'messages' ? 'Personal' : 'Work / School'}</span>
          </div>

          {/* Contact Buttons */}
          <div className="space-y-1 overflow-y-auto max-h-[220px] pr-0.5">
            {activeContactsList.map((contact) => (
              <button
                key={contact}
                onClick={() => setActiveContact(contact)}
                className={`w-full py-1.5 px-2.5 rounded border-2 border-black text-left font-mono font-bold text-[11px] transition shadow-sm truncate ${
                  activeContact === contact
                    ? 'bg-[#D9D9D9] text-[#1F1F1F] font-extrabold translate-x-0.5 border-l-4 border-l-[#4626A4]'
                    : 'bg-[#401C40] text-purple-100 hover:bg-[#5C2B5C]'
                }`}
              >
                {contact}
              </button>
            ))}
          </div>
        </div>

        {/* Bottom Action Bar: Mail Envelope & Backpack matching SVG positions */}
        <div className="flex items-center justify-around pt-2.5 border-t-4 border-black bg-[#240724] pb-1">
          {/* Left: Mail Envelope (Personal Messages) */}
          <button
            onClick={() => {
              setActiveTab('messages');
              setActiveContact('Aelita');
            }}
            className={`p-2 rounded-xl border-2 border-black transition shadow-md ${
              activeTab === 'messages'
                ? 'bg-purple-600 text-white ring-2 ring-purple-400'
                : 'bg-[#D9D9D9] text-[#1F1F1F] hover:bg-white'
            }`}
            title="Personal Messages (DMs)"
          >
            <Mail size={20} />
          </button>

          {/* Right: Backpack (Comms Work/School) */}
          <button
            onClick={() => {
              setActiveTab('comms');
              setActiveContact('Dean Cassian Rook');
            }}
            className={`p-2 rounded-xl border-2 border-black transition shadow-md ${
              activeTab === 'comms'
                ? 'bg-purple-600 text-white ring-2 ring-purple-400'
                : 'bg-[#D9D9D9] text-[#1F1F1F] hover:bg-white'
            }`}
            title="Comms (Work & School)"
          >
            <span className="text-lg">🎒</span>
          </button>
        </div>
      </div>

      {/* ------------------------------------------------------------------ */}
      {/* RIGHT MAIN PANEL (EXACT SVG SPEC: #D9D9D9 INSET CANVAS)            */}
      {/* ------------------------------------------------------------------ */}
      <div className="flex-1 flex flex-col justify-between pl-3 space-y-2.5 overflow-hidden">
        {/* Main Inset Canvas matching SVG path fill="#D9D9D9" */}
        <div className="flex-1 flex flex-col justify-between bg-[#D9D9D9] rounded-lg border-2 border-black p-3 space-y-2 overflow-hidden shadow-md">
          {/* Header matching SVG: Left-aligned bold purple COMMS title with solid #000000 underline */}
          <div className="border-b-4 border-black pb-1.5 flex items-center justify-between">
            <h1 className="font-serif-y2k text-2xl font-black text-[#673AB7] tracking-widest uppercase">
              COMMS
            </h1>
            <span className="font-mono text-[10px] font-bold text-slate-700 bg-white/80 px-2 py-0.5 rounded border border-slate-400">
              Channel: {activeContact}
            </span>
          </div>

          {/* Active Conversation Feed */}
          <div className="flex-1 overflow-y-auto space-y-2.5 p-2 bg-white/60 rounded border border-slate-400">
            {chatFeed.map((msg) => (
              <div
                key={msg.id}
                className={`p-2.5 rounded-lg border-2 border-black shadow-sm max-w-[85%] ${
                  msg.user.startsWith('You')
                    ? 'bg-[#E5D7FA] text-purple-950 ml-auto'
                    : 'bg-white text-slate-900 mr-auto'
                }`}
              >
                <div className="flex justify-between items-center text-[10px] font-mono font-bold mb-1 border-b border-slate-300 pb-0.5">
                  <span>{msg.user}</span>
                  <span className="opacity-60">{msg.time}</span>
                </div>
                <div className="text-xs font-sans font-medium">{msg.text}</div>
              </div>
            ))}
          </div>
        </div>

        {/* ------------------------------------------------------------------ */}
        {/* BOTTOM INPUT BAR (EXACT SVG SPEC: rect fill="#D9D9D9" + icons)     */}
        {/* ------------------------------------------------------------------ */}
        <div className="h-10 bg-[#D9D9D9] rounded-lg border-2 border-black flex items-center px-3 gap-2 shrink-0 shadow">
          {/* Plus icon matching SVG path d="M209 304..." */}
          <button
            onClick={() => setComposing(true)}
            className="p-1 rounded bg-white hover:bg-slate-100 text-[#1F1F1F] font-bold border border-slate-400 transition"
            title="Add Attachment / Compose"
          >
            <Plus size={16} />
          </button>

          <input
            type="text"
            value={chatInput}
            onChange={(e) => setChatInput(e.target.value)}
            onKeyDown={handleSendChat}
            placeholder={`Send message to ${activeContact}...`}
            className="flex-1 bg-transparent text-xs text-[#1F1F1F] outline-none font-sans font-semibold placeholder-slate-600"
          />

          {/* Smiley icon matching SVG smiley path */}
          <button
            onClick={handleSendChat}
            className="p-1 rounded bg-white hover:bg-slate-100 text-[#1F1F1F] font-bold border border-slate-400 transition"
            title="Send Message"
          >
            <Smile size={16} />
          </button>
        </div>
      </div>

      {/* COMPOSE MODAL */}
      {composing && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
          <div className="w-96 rounded-2xl border-4 border-black bg-[#D9D9D9] p-4 text-slate-900 space-y-3 shadow-2xl">
            <div className="flex justify-between border-b-2 border-black pb-2 font-mono font-bold text-[#673AB7]">
              <span>Compose Transmission</span>
              <button onClick={() => setComposing(false)} className="hover:text-red-700">✕</button>
            </div>

            <div className="space-y-2 text-xs">
              <div>
                <label className="text-[10px] block font-mono font-bold">Recipient:</label>
                <select
                  value={composeRecipient}
                  onChange={(e) => setComposeRecipient(e.target.value)}
                  className="w-full rounded-lg border-2 border-black bg-white text-slate-900 p-1.5 outline-none font-bold"
                >
                  {activeContactsList.map((c) => (
                    <option key={c}>{c}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="text-[10px] block font-mono font-bold">Subject:</label>
                <input
                  type="text"
                  value={composeSubject}
                  onChange={(e) => setComposeSubject(e.target.value)}
                  placeholder="Subject line..."
                  className="w-full rounded-lg border-2 border-black bg-white text-slate-900 p-1.5 outline-none font-bold"
                />
              </div>

              <div>
                <label className="text-[10px] block font-mono font-bold">Message:</label>
                <textarea
                  rows={4}
                  value={composeBody}
                  onChange={(e) => setComposeBody(e.target.value)}
                  placeholder="Write message..."
                  className="w-full rounded-lg border-2 border-black bg-white text-slate-900 p-1.5 outline-none font-medium resize-none"
                />
              </div>
            </div>

            <div className="flex justify-end gap-2 pt-1">
              <button
                onClick={() => setComposing(false)}
                className="px-3 py-1.5 rounded-lg border-2 border-black bg-white text-slate-900 font-bold hover:bg-slate-200"
              >
                Cancel
              </button>
              <button
                onClick={handleSendCompose}
                className="px-4 py-1.5 rounded-lg border-2 border-black bg-[#673AB7] text-white font-bold hover:bg-purple-700"
              >
                Send
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
